import * as THREE from './vendor/three.module.min.js';
const C=THREE;
export class World {
 constructor(canvas){this.canvas=canvas;this.renderer=new C.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});this.renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));this.renderer.shadowMap.enabled=true;this.renderer.shadowMap.type=C.PCFSoftShadowMap;this.renderer.outputColorSpace=C.SRGBColorSpace;this.renderer.toneMapping=C.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.05;this.scene=new C.Scene();this.scene.fog=new C.FogExp2('#cbd4ef',.009);this.camera=new C.PerspectiveCamera(42,1,.1,240);this.camera.position.set(9,7,15);this.look=new C.Vector3(-3,.5,-4);this.targetLook=this.look.clone();this.clock=0;this.lane=0;this.jumpAt=-10;this.spinAt=-10;this.hitAt=-10;this.boost=false;this.playing=false;
 this.geos={sphere:new C.SphereGeometry(1,24,16),small:new C.SphereGeometry(1,12,8)};this.materials={white:new C.MeshStandardMaterial({color:'#fffafc',roughness:.82}),pink:new C.MeshStandardMaterial({color:'#efa0bd',roughness:.7}),dark:new C.MeshStandardMaterial({color:'#3c355c',roughness:.3}),purple:new C.MeshStandardMaterial({color:'#9276df',roughness:.48}),mint:new C.MeshStandardMaterial({color:'#94e5d2',roughness:.45}),gold:new C.MeshStandardMaterial({color:'#ffdc7d',roughness:.3,metalness:.18,emissive:'#d38d1f',emissiveIntensity:.14})};
 this.scene.add(new C.HemisphereLight('#fff8f2','#9d8bbd',2.7));const sun=new C.DirectionalLight('#fff7e0',3.1);sun.position.set(-15,25,15);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-20,right:20,top:25,bottom:-20,near:.5,far:80});sun.shadow.bias=-.001;this.scene.add(sun);
 this.skyMat=new C.ShaderMaterial({side:C.BackSide,depthWrite:false,uniforms:{top:{value:new C.Color('#8dbfec')},bottom:{value:new C.Color('#f5dfe9')}},vertexShader:'varying vec3 p;void main(){p=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'uniform vec3 top;uniform vec3 bottom;varying vec3 p;void main(){float h=smoothstep(-.18,.6,normalize(p).y);gl_FragColor=vec4(mix(bottom,top,h),1.);}'});this.scene.add(new C.Mesh(new C.SphereGeometry(180,24,24),this.skyMat));
 this.clouds=[];this.distant=[];this.notes=new Map();this.particles=[];this.rings=[];
 this.homeCloud=this.cloud(2.8);this.homeCloud.position.set(0,-1.75,2);this.scene.add(this.homeCloud);
 for(let i=0;i<16;i++){for(let lane=-1;lane<=1;lane++){const c=this.cloud(1.15);c.userData={row:i,lane};this.clouds.push(c);this.scene.add(c);}}
 for(let i=0;i<20;i++){const c=this.cloud(2.5+(i%4));c.position.set(Math.sin(i*2.39)*30,-5-(i%4)*2,-10-i*5);c.scale.multiplyScalar(1.2);this.scene.add(c);this.distant.push(c);}
 this.bunny=this.makeBunny();this.bunny.position.set(0,0,2);this.scene.add(this.bunny);
 const ringMat=new C.MeshStandardMaterial({color:'#fbdcbf',roughness:.7,transparent:true,opacity:.56});for(let i=0;i<3;i++){const ring=new C.Mesh(new C.TorusGeometry(14+i*.6,.1,8,100,Math.PI),ringMat.clone());ring.material.color.set(['#fbbfce','#fbdec0','#dde4fd'][i]);ring.position.set(0,-2,-38);this.scene.add(ring);}
 this.sun=this.sphere(this.materials.gold,[-14,14,-55],[5,5,2]);this.sun.material=new C.MeshBasicMaterial({color:'#fff1c5'});this.scene.add(this.sun);
 for(let i=0;i<7;i++){const star=this.star(.17+(i%3)*.09);star.position.set(Math.sin(i*8)*16,3+Math.cos(i*3)*5,-i*7);this.scene.add(star);this.rings.push(star);}
 const points=[];for(let i=0;i<180;i++)points.push((Math.random()-.5)*100,Math.random()*40-12,-Math.random()*120);const geo=new C.BufferGeometry();geo.setAttribute('position',new C.Float32BufferAttribute(points,3));this.dust=new C.Points(geo,new C.PointsMaterial({color:'#ffffff',size:.09,transparent:true,opacity:.75}));this.scene.add(this.dust);
 this.halo=new C.Mesh(new C.TorusGeometry(1.18,.035,8,64),new C.MeshBasicMaterial({color:'#e7bbff',transparent:true,opacity:.8}));this.halo.rotation.x=-Math.PI/2;this.halo.position.set(0,.65,2);this.scene.add(this.halo);
 this.resize();window.addEventListener('resize',()=>this.resize());}
 sphere(mat,pos,scale=[1,1,1],small=false){const m=new C.Mesh(small?this.geos.small:this.geos.sphere,mat);m.position.set(...pos);m.scale.set(...scale);m.castShadow=true;m.receiveShadow=true;return m;}
 cloud(size=1){const group=new C.Group();const arr=[[0,0,0,1.1,.43,.68],[-.78,-.05,0,.75,.37,.6],[.8,-.04,0,.68,.38,.62],[-.35,.12,-.15,.65,.5,.64],[.35,.17,-.18,.65,.53,.6],[0,-.13,.37,.85,.35,.55]];arr.forEach(([x,y,z,a,b,c])=>group.add(this.sphere(this.materials.white,[x*size,y*size,z*size],[a*size,b*size,c*size],true)));return group;}
 makeBunny(){const g=new C.Group(),m=this.materials;g.add(this.sphere(m.white,[0,.92,0],[.64,.79,.51]));g.add(this.sphere(m.white,[0,1.96,.1],[.83,.71,.65]));this.ears=[];[-1,1].forEach(s=>{const ear=new C.Group();ear.position.set(s*.40,2.37,.06);ear.rotation.z=-s*.13;ear.add(this.sphere(m.white,[0,.63,0],[.23,.86,.22]));ear.add(this.sphere(m.pink,[0,.65,.175],[.125,.65,.045]));g.add(ear);this.ears.push(ear);g.add(this.sphere(m.dark,[s*.285,2.06,.682],[.08,.105,.035]));g.add(this.sphere(m.white,[s*.285-.025,2.10,.711],[.023,.026,.014]));g.add(this.sphere(m.pink,[s*.47,1.83,.643],[.14,.072,.02]));g.add(this.sphere(m.purple,[s*.82,2,.06],[.16,.29,.32]));g.add(this.sphere(m.mint,[s*.91,2,.09],[.055,.2,.23]));});g.add(this.sphere(m.pink,[0,1.84,.745],[.075,.047,.034]));const mouth=new C.Mesh(new C.TorusGeometry(.068,.009,5,16,Math.PI),m.dark);mouth.rotation.z=Math.PI;mouth.position.set(0,1.785,.735);g.add(mouth);
 const band=new C.Mesh(new C.TorusGeometry(.83,.073,8,40,Math.PI),m.purple);band.position.set(0,2,.07);g.add(band);
 this.arms=[];[-1,1].forEach(s=>{const arm=this.sphere(m.white,[s*.61,1.17,.04],[.23,.43,.24]);arm.rotation.z=s*.5;g.add(arm);this.arms.push(arm);g.add(this.sphere(m.white,[s*.34,.28,.27],[.31,.26,.45]));});g.add(this.sphere(m.white,[0,.70,-.54],[.27,.27,.27]));const collar=new C.Mesh(new C.TorusGeometry(.49,.11,8,36),m.purple);collar.rotation.x=Math.PI/2;collar.position.y=1.48;g.add(collar);const tag=this.sphere(m.gold,[0,1.32,.50],[.12,.14,.06]);g.add(tag);return g;}
 star(size=.3){const group=new C.Group();const shape=new C.Shape();for(let i=0;i<10;i++){const a=i*Math.PI/5+Math.PI/2,r=i%2?size*.45:size;if(i===0)shape.moveTo(Math.cos(a)*r,Math.sin(a)*r);else shape.lineTo(Math.cos(a)*r,Math.sin(a)*r);}shape.closePath();const mesh=new C.Mesh(new C.ExtrudeGeometry(shape,{depth:size*.25,bevelEnabled:true,bevelSegments:1,steps:1,bevelSize:size*.07,bevelThickness:size*.05}),this.materials.gold);group.add(mesh);return group;}
 note(type){const g=new C.Group();if(type==='carrot'){const m=new C.Mesh(new C.ConeGeometry(.22,.7,10),new C.MeshStandardMaterial({color:'#f5a459',roughness:.7}));m.rotation.z=Math.PI;g.add(m);for(let i=-1;i<=1;i++){const leaf=this.sphere(this.materials.mint,[i*.09,.4,0],[.055,.19,.05],true);leaf.rotation.z=-i*.5;g.add(leaf);}}else if(type==='storm'){g.add(this.sphere(new C.MeshStandardMaterial({color:'#9991bf',roughness:.8}),[0,0,0],[.5,.28,.3],true));const bolt=new C.Mesh(new C.ConeGeometry(.16,.65,3),this.materials.gold);bolt.position.y=-.3;bolt.rotation.z=.25;g.add(bolt);}else{const mat=new C.MeshStandardMaterial({color:'#c093ff',roughness:.24,metalness:.18,emissive:'#9947ea',emissiveIntensity:.16});g.add(this.sphere(mat,[-.11,-.14,0],[.22,.16,.13]));const stem=new C.Mesh(new C.CylinderGeometry(.045,.045,.64,8),mat);stem.position.set(.075,.14,0);g.add(stem);const flag=this.sphere(mat,[.20,.42,0],[.18,.08,.08]);flag.rotation.z=-.35;g.add(flag);}return g;}
 setTrack(track){this.skyMat.uniforms.top.value.set(track.sky[0]);this.skyMat.uniforms.bottom.value.set(track.sky[1]);this.scene.fog.color.set(track.sky[1]);this.sun.material.color.set(track.id==='starlight'?'#f0ecff':'#fff1c5');}
 setTargets(targets){for(const v of this.notes.values())this.scene.remove(v);this.notes.clear();targets.forEach(n=>{const group=this.note(n.type);group.userData=n;this.notes.set(n.id,group);this.scene.add(group);});}
 burst(lane,color='#ffdc7d'){for(let i=0;i<10;i++){const mesh=this.sphere(new C.MeshBasicMaterial({color,transparent:true}),[lane*3.3,1.1,2],[.07,.07,.07],true);mesh.userData={life:1,vx:(Math.random()-.5)*4,vy:Math.random()*4,vz:(Math.random()-.5)*4};this.scene.add(mesh);this.particles.push(mesh);}}
 jump(spin=false){this.jumpAt=this.clock;if(spin)this.spinAt=this.clock;}
 resize(){const w=innerWidth,h=innerHeight;this.renderer.setSize(w,h);this.camera.aspect=w/h;this.camera.updateProjectionMatrix();}
 render(dt,beat=0,playing=false){this.clock+=dt;this.playing=playing;const t=this.clock,bounce=Math.abs(Math.sin((playing?beat:t*1.6)*Math.PI));const mobile=innerWidth<740;
 const cam=playing?new C.Vector3(0,7.4,13):new C.Vector3(mobile?8:9,mobile?7:6.6,mobile?18:16);const look=playing?new C.Vector3(0,.7,-7):new C.Vector3(mobile?-1.2:-4.4,mobile?.3:.8,-3);this.camera.position.lerp(cam,Math.min(1,dt*2));this.look.lerp(look,Math.min(1,dt*2));this.camera.lookAt(this.look);
 this.homeCloud.visible=!playing;this.bunny.position.x=C.MathUtils.lerp(this.bunny.position.x,playing?this.lane*3.3:0,Math.min(1,dt*14));const j=this.clock-this.jumpAt,hop=j<.5?Math.sin(j/.5*Math.PI)*1.9:0;this.bunny.position.y=(playing?.67:.24)+bounce*.10+hop;this.bunny.rotation.z=Math.sin((playing?beat:t)*Math.PI)*.045;this.bunny.rotation.y=playing?-.12:Math.sin(t*.6)*.16-.20;if(this.clock-this.spinAt<.6)this.bunny.rotation.y+=(this.clock-this.spinAt)/.6*Math.PI*2;this.bunny.scale.setScalar(playing?.84:1.43);this.ears.forEach((e,i)=>e.rotation.z=(i?-.13:.13)+Math.sin(t*4+i)*.06);this.arms.forEach((a,i)=>a.rotation.z=(i?1:-1)*(.45+bounce*.28+hop*.15));
 this.halo.position.x=this.bunny.position.x;this.halo.scale.setScalar(1+bounce*.15);this.halo.material.opacity=.4+bounce*.35;this.halo.material.color.set(this.boost?'#ffe48f':'#cba0f7');
 this.clouds.forEach(c=>{const row=c.userData.row;const travel=playing?beat:0;const cycle=((row-travel)%16+16)%16;c.position.set(c.userData.lane*3.3, -.2+Math.sin(row*3+t*.4)*.035, 2-cycle*3.8);c.visible=playing||row>0;});
 this.distant.forEach((c,i)=>{c.position.x+=Math.sin(t*.3+i)*dt*.05;c.position.y+=Math.sin(t*.5+i)*dt*.035;});this.rings.forEach((r,i)=>{r.rotation.y=t*.25+i;r.rotation.z=Math.sin(t*.4+i)*.2;});
 this.notes.forEach((n)=>{const target=n.userData;const z=2-(target.beat-beat)*3.8;n.visible=playing&&!target.done&&z<8&&z>-65;n.position.set(target.lane*3.3,1.05+Math.sin(t*3+target.beat)*.12,z);n.rotation.y=Math.sin(t*2)*.22;});
 for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i],v=p.userData;v.life-=dt*1.5;p.position.x+=v.vx*dt;p.position.y+=v.vy*dt;p.position.z+=v.vz*dt;v.vy-=6*dt;p.material.opacity=Math.max(0,v.life);if(v.life<=0){this.scene.remove(p);p.material.dispose();this.particles.splice(i,1);}}
 this.renderer.render(this.scene,this.camera);}
}
